<?php
namespace App\Console\Commands;
use App\Models\HrCertification;use App\Models\HrProbationReview;use App\Models\User;use Carbon\Carbon;use Illuminate\Console\Command;use Illuminate\Support\Facades\Mail;
class SendHrComplianceReminders extends Command{protected $signature='hr:send-compliance-reminders';protected $description='Send staged certification expiry and probation review reminders';public function handle(){ $dates=collect([30,7,1])->map(fn($d)=>today()->addDays($d)->toDateString());$certifications=HrCertification::with('employee')->whereIn('expires_at',$dates)->get();foreach($certifications as $certification){if($certification->employee?->email)Mail::raw("Your {$certification->name} certification expires on {$certification->expires_at->format('Y-m-d')}. Please submit a renewal.",fn($mail)=>$mail->to($certification->employee->email)->subject('Certification expiry reminder'));}$reviews=HrProbationReview::with('employee')->where('status','pending')->whereIn('due_date',$dates)->get();$admins=User::allAdmins();foreach($reviews as $review){foreach($admins as $admin){Mail::raw("Probation review due: {$review->employee?->name}, day {$review->review_day}, due {$review->due_date->format('Y-m-d')}.",fn($mail)=>$mail->to($admin->email)->subject('Probation review reminder'));}}$this->info("Sent reminders for {$certifications->count()} certifications and {$reviews->count()} probation reviews.");}}
